def get_tau(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return 1

def calculate_tau_x_squared(x):
    # x^2 = prod(p_i^(2a_i))
    # tau(x^2) = prod(2a_i + 1)
    factors = {}
    d = 2
    temp = x
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    tau_x_sq = 1
    for p, a in factors.items():
        tau_x_sq *= (2 * a + 1)
    return tau_x_sq

def calculate_N(tau_x_sq):
    return (tau_x_sq - 1) // 2

